#include <torch/extension.h>

torch::Tensor gelu_bias_add(torch::Tensor x, torch::Tensor bias);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("gelu_bias_add", &gelu_bias_add, "Fused GELU + bias add");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <math_constants.h>

__global__ void gelu_bias_add_kernel(
    const float* __restrict__ x,
    const float* __restrict__ bias,
    float* __restrict__ out,
    int N, int W,
    int bias_n, int bias_w
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * W;
    if (idx >= total) return;

    int n = idx / W;
    int w = idx % W;

    float val = x[idx];
    // GELU via erf approximation (matches PyTorch default)
    float gelu_val = 0.5f * val * (1.0f + erff(val * 0.7071067811865476f));

    // bias shape is [bias_n, 1, 1, bias_w] broadcast; bias_n and bias_w may be 1
    int bn = (bias_n > 1) ? n : 0;
    int bw = (bias_w > 1) ? w : 0;
    float b = bias[bn * bias_w + bw];

    out[idx] = gelu_val + b;
}

torch::Tensor gelu_bias_add(torch::Tensor x, torch::Tensor bias) {
    // x shape: [N, 1, 1, W] (after min+sum reductions, may be channels_last or contiguous)
    // bias shape: [bias_n, 1, 1, bias_w] or [1,1,1,1] etc.
    auto x_c = x.contiguous();
    auto bias_c = bias.contiguous();

    int N = x_c.size(0);
    int W = x_c.size(3);
    int bias_n = bias_c.size(0);
    int bias_w = bias_c.size(3);

    auto out = torch::empty_like(x_c);

    int total = N * W;
    int threads = 256;
    int blocks = (total + threads - 1) / threads;

    gelu_bias_add_kernel<<<blocks, threads>>>(
        x_c.data_ptr<float>(),
        bias_c.data_ptr<float>(),
        out.data_ptr<float>(),
        N, W,
        bias_n, bias_w
    );

    return out;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        A model that performs a convolution transpose, minimum operation, sum operation, GELU activation and addition.
        """
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, output_padding, bias_shape):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        self.conv_transpose = nn.ConvTranspose2d(in_channels, out_channels, kernel_size, stride, padding, output_padding)
        self.conv_transpose = self.conv_transpose.to(memory_format=torch.channels_last)
        self.bias = nn.Parameter(torch.randn(bias_shape))
        # <<<END_IMPROVE>>>

    def forward(self, x):
        # <<<IMPROVE:forward_stmt_1>>>
        if x.is_cuda:
            if not x.is_contiguous(memory_format=torch.channels_last):
                x = x.contiguous(memory_format=torch.channels_last)
            x = self.conv_transpose(x)
        else:
            x = self.conv_transpose(x)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        x = torch.amin(x, dim=1, keepdim=True)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_3>>>
        x = torch.sum(x, dim=2, keepdim=True)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_4>>>
        x = _stark_get_extension().gelu_bias_add(x.contiguous(), self.bias.contiguous())
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_5>>>
        # bias add fused into forward_stmt_4
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_6>>>
        return x
        # <<<END_IMPROVE>>>

