#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <float.h>

// Each thread handles one (n, w) output element.
// Iterates over all channels c to compute min, then over all h to sum, then GELU + bias.
__global__ void fused_min_sum_gelu_add_kernel(
    const float* __restrict__ input,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int C, int H, int W,
    int64_t s0, int64_t s1, int64_t s2, int64_t s3,  // input strides
    int bias_numel
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * W;
    if (idx >= total) return;

    int n = idx / W;
    int w = idx % W;

    // For each h, compute min over channels, then accumulate sum over h
    float sum_val = 0.0f;
    for (int h = 0; h < H; h++) {
        float ch_min = FLT_MAX;
        for (int c = 0; c < C; c++) {
            float val = __ldg(&input[n * s0 + c * s1 + h * s2 + w * s3]);
            if (val < ch_min) ch_min = val;
        }
        sum_val += ch_min;
    }

    // GELU using erf form (matches PyTorch default)
    float gelu_val = 0.5f * sum_val * (1.0f + erff(sum_val * 0.7071067811865476f));

    // Bias: shape [1,1,1] or similar small broadcast; use flat index modulo numel
    float bias_val = __ldg(&bias[(n * 1 * 1 * 1 + 0 * 1 * 1 + 0 * 1 + 0) % bias_numel]);

    output[n * W + w] = gelu_val + bias_val;
}

torch::Tensor convtranspose_min_sum_gelu_add_cuda(torch::Tensor x, torch::Tensor bias) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(bias.is_cuda(), "bias must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    TORCH_CHECK(x.dim() == 4, "x must be 4D (N,C,H,W)");

    int N = x.size(0);
    int C = x.size(1);
    int H = x.size(2);
    int W = x.size(3);

    int64_t s0 = x.stride(0);
    int64_t s1 = x.stride(1);
    int64_t s2 = x.stride(2);
    int64_t s3 = x.stride(3);

    // Output shape: (N, 1, 1, W)
    auto output_flat = torch::empty({N, W}, x.options().memory_format(c10::MemoryFormat::Contiguous));

    int total = N * W;
    int block = 256;
    int grid = (total + block - 1) / block;

    const float* x_ptr = x.data_ptr<float>();
    const float* bias_ptr = bias.data_ptr<float>();
    float* out_ptr = output_flat.data_ptr<float>();
    int bias_numel = (int)bias.numel();

    fused_min_sum_gelu_add_kernel<<<grid, block>>>(
        x_ptr, bias_ptr, out_ptr,
        N, C, H, W,
        s0, s1, s2, s3,
        bias_numel
    );

    // Reshape to (N, 1, 1, W) to match expected output shape
    return output_flat.view({N, 1, 1, W});
}
